package com.sih.support.service; import com.sih.support.dto.SupportDtos.*; import com.sih.support.entity.*; import com.sih.support.repository.Repositories.*; import com.sih.shared.tenant.TenantContext; import java.time.*; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import org.springframework.web.server.*; @Service @Transactional public class SupportWorkflowService {final Meals meals;final EquipmentRepo equipment;final WorkOrders work;final CleaningRepo cleaning;public SupportWorkflowService(Meals a,EquipmentRepo b,WorkOrders c,CleaningRepo d){meals=a;equipment=b;work=c;cleaning=d;}String t(){return TenantContext.requireCurrentTenant();}MealOrder meal(Long i){return meals.findByIdAndTenantId(i,t()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}Equipment asset(Long i){return equipment.findByIdAndTenantId(i,t()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}MaintenanceWorkOrder job(Long i){return work.findByIdAndTenantId(i,t()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}CleaningTask task(Long i){return cleaning.findByIdAndTenantId(i,t()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}public List<Meal> meals(){return meals.findByTenantIdOrderByScheduledOnDesc(t()).stream().map(this::m).toList();}public Meal createMeal(MealReq r){MealOrder x=new MealOrder();x.setPatientRef(r.patientRef());x.setDietCode(r.dietCode());x.setMealType(r.mealType());x.setScheduledOn(r.scheduledOn());x.setBedRef(r.bedRef());return m(meals.save(x));}public Meal prepare(Long i){MealOrder x=meal(i);if(!"REQUESTED".equals(x.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT);x.setStatus("PREPARED");return m(x);}public Meal deliver(Long i){MealOrder x=meal(i);if(!"PREPARED".equals(x.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT);x.setStatus("DELIVERED");x.setDeliveredAt(OffsetDateTime.now());return m(x);}public List<Asset> equipment(){return equipment.findByTenantIdOrderByNameAsc(t()).stream().map(this::a).toList();}public Asset createEquipment(EquipmentReq r){Equipment x=new Equipment();x.setAssetTag(r.assetTag());x.setName(r.name());x.setLocation(r.location());x.setCritical(r.critical());return a(equipment.save(x));}public List<Work> work(){return work.findByTenantIdOrderByDueOnAsc(t()).stream().map(this::w).toList();}public Work createWork(WorkReq r){Equipment e=asset(r.equipmentId());e.setStatus("MAINTENANCE");MaintenanceWorkOrder x=new MaintenanceWorkOrder();x.setEquipment(e);x.setTitle(r.title());x.setType(r.type());x.setDueOn(r.dueOn());x.setAssignedTo(r.assignedTo());return w(work.save(x));}public Work completeWork(Long i){MaintenanceWorkOrder x=job(i);if(!"OPEN".equals(x.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT);x.setStatus("COMPLETED");x.setCompletedAt(OffsetDateTime.now());x.getEquipment().setStatus("OPERATIONAL");x.getEquipment().setLastMaintenance(LocalDate.now());return w(x);}public List<Cleaning> cleaning(){return cleaning.findByTenantIdOrderByRequestedAtDesc(t()).stream().map(this::c).toList();}public Cleaning createCleaning(CleaningReq r){CleaningTask x=new CleaningTask();x.setBedRef(r.bedRef());x.setUnitName(r.unitName());x.setCleaningType(r.cleaningType());return c(cleaning.save(x));}public Cleaning completeCleaning(Long i){CleaningTask x=task(i);if(!"REQUESTED".equals(x.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT);x.setStatus("COMPLETED");x.setCompletedAt(OffsetDateTime.now());return c(x);}Meal m(MealOrder x){return new Meal(x.getId(),x.getPatientRef(),x.getDietCode(),x.getMealType(),x.getScheduledOn(),x.getBedRef(),x.getStatus(),x.getDeliveredAt());}Asset a(Equipment x){return new Asset(x.getId(),x.getAssetTag(),x.getName(),x.getLocation(),x.isCritical(),x.getStatus(),x.getLastMaintenance());}Work w(MaintenanceWorkOrder x){return new Work(x.getId(),x.getEquipment().getId(),x.getEquipment().getName(),x.getTitle(),x.getType(),x.getDueOn(),x.getStatus(),x.getAssignedTo(),x.getCompletedAt());}Cleaning c(CleaningTask x){return new Cleaning(x.getId(),x.getBedRef(),x.getUnitName(),x.getCleaningType(),x.getStatus(),x.getRequestedAt(),x.getCompletedAt());}}